      lean: (up ? -.07 : .07) * k, hairSwing: (up ? -.4 : .4) * k, handR: up ? [4.9, -13.4] : [-1.6, -3.3], handPoseR: 'point', handL: [-2.6, -4.6], handPoseL: 'fist',
