  withBoil(0, () => { line(sp, { stroke: AL.purple, lw: .42, smooth: true }); line(sp.map(([px, py]) => [px * .9, cy + (py - cy) * .9]), { stroke: '#FFFFFF', lw: .18, smooth: true }); });
