      o.handL = [0, -sh - 2]; o.handR = [3, -sh - 3]; o.handPoseL = o.handPoseR = 'palm';
      o.aL = o.aR = 1.6; o.flipNear = -2; o.flipFar = -1.8; o.wings = .65;
