      const a = Math.PI + i * Math.PI / 4;
      line([[Math.cos(a) * 1.65, Math.sin(a) * 1.65 - .2],
        [Math.cos(a) * 2.2, Math.sin(a) * 2.2 - .2]], { stroke: '#E9AB32', lw: .18, alpha: glow });
