  if (clamp(o.steam || 0) > .01) rsSteam(clamp(o.steam), t, A, s);
  if (gl > .01) rsSparks(gl, t);
  A.top = toPx(0, -29.6);
  X.restore();
  if (clamp(o.scan || 0) > .01) rsScan(clamp(o.scan), A, s, t, o.lookX || 0, y);
  if (o.emote && (o.emoteK ?? 1) > .02) rsEmote(o.emote, A, s, o.emoteK ?? 1, t);
