    X.globalAlpha = .9 * k; ellipse(cx, fy, 4 * s, .7 * s, { fill: null, stroke: '#FF5A5A', lwPx: 3 });
    const sl = frac(t * 1.3); line([[lerp(ex, cx - 4 * s, sl), lerp(ey, fy, sl)], [lerp(ex, cx + 4 * s, sl), lerp(ey, fy, sl)]], { stroke: '#FFC4C4', lwPx: 3 });
